// Общие помощники тестов статусов симуляции (#94c3ab): сессии ролей, подмена GET simulations (route.fetch + правка / fulfill).
// Только подмена ЧТЕНИЯ: ни один запрос не меняется на сервере, звонки не стартуют, статусы не переключаются.
import * as path from 'path';
import { Page, Route, expect } from '@playwright/test';

export const HASH = '#94c3ab · #6a993d738eac0db9d694c3ab';
/** Менеджер аккаунта testim (слот bizt) и מנהל/ת מגייס/ת testim (слот user-2) — как в тестах квоты. Паролей нет, только сохранённые сессии. */
export const MANAGER_STATE = path.resolve(__dirname, '../../../auth/bizt.json');
export const RECRUITER_STATE = path.resolve(__dirname, '../../../auth/user-2.json');
/** Несуществующая симуляция: серверные проверки не могут ничего изменить даже при сломанной проверке статуса. */
export const NO_SUCH_SIMULATION = '00000000-0000-0000-0000-000000000094';

const REST_SIMULATIONS = '/rest/v1/simulations';

/** Строка embed-запроса «in_progress:attempts(count)» → в UI «attempts_in_progress». */
export type SimRow = Record<string, unknown> & { id: string; status: string; in_progress?: { count: number }[]; candidates?: { count: number }[] };

/** Список /simulations: GET simulations с embed «in_progress:attempts(count)» и фильтром in_progress.status. */
const isListQuery = (u: URL) => u.pathname === REST_SIMULATIONS && (u.searchParams.get('select') || '').includes('in_progress');
/** Редактор: GET simulations?select=*&id=eq.<id> (maybeSingle → объект). */
const isEditorQuery = (u: URL, id: string) => u.pathname === REST_SIMULATIONS && u.searchParams.get('select') === '*' && u.searchParams.get('id') === `eq.${id}`;
/** Ящик «מועמד חדש»: simulations?select=id,name,version,role_title,status&status=in.(active,locked). */
const isInviteQuery = (u: URL) => u.pathname === REST_SIMULATIONS && u.searchParams.get('status') === 'in.(active,locked)';

async function onGet(page: Page, match: (u: URL) => boolean, handler: (route: Route, u: URL) => Promise<void>) {
  await page.route('**/rest/v1/simulations*', async (route) => {
    const u = new URL(route.request().url());
    if (route.request().method() !== 'GET' || !match(u)) return route.fallback();
    await handler(route, u);
  });
}

/**
 * Список /simulations: настоящий ответ, но `mutate` меняет строки. Возвращает «считыватель» id строки, которую заперли
 * (заполняется после первого ответа).
 */
export async function mockSimulationsList(page: Page, mutate: (rows: SimRow[]) => SimRow[]) {
  await onGet(page, isListQuery, async (route) => {
    const res = await route.fetch();
    const rows = (await res.json()) as SimRow[];
    await route.fulfill({ response: res, json: mutate(rows) });
  });
}

/** Запирает одну строку списка: status locked + 1 официальная попытка в процессе. Возвращает id запертой строки. */
export function lockOneRow(box: { id?: string; lockedTotal?: number }) {
  return (rows: SimRow[]): SimRow[] => {
    const target = rows.find((r) => r.status === 'active') ?? rows.find((r) => r.status !== 'draft' && r.status !== 'locked') ?? rows[0];
    if (!target) return rows;
    box.id = target.id;
    const out = rows.map((r) => (r.id === target.id ? { ...r, status: 'locked', in_progress: [{ count: 1 }] } : r));
    box.lockedTotal = out.filter((r) => r.status === 'locked').length;
    return out;
  };
}

/** Редактор: настоящая строка симуляции `id`, но status = locked. */
export async function mockEditorLocked(page: Page, id: string) {
  await onGet(page, (u) => isEditorQuery(u, id), async (route) => {
    const res = await route.fetch();
    const body = await res.json();
    const row = Array.isArray(body) ? body[0] : body;
    if (row) row.status = 'locked';
    await route.fulfill({ response: res, json: body });
  });
}

/** Ящик «מועמד חדש»: полностью подменённый ответ (пусто или единственная locked). */
export async function mockInviteSimulations(page: Page, rows: Record<string, unknown>[]) {
  await onGet(page, isInviteQuery, async (route) => {
    await route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify(rows) });
  });
}

/** Страховка: create_candidate обрывается и считается — тест обязан закончить с 0. */
export async function blockCandidateCreation(page: Page): Promise<() => number> {
  let n = 0;
  await page.route('**/rest/v1/rpc/create_candidate*', (route) => {
    n++;
    return route.abort();
  });
  return () => n;
}

/** Страховка: ни одного изменения статусов/версий симуляций за тест. */
export async function blockSimulationWrites(page: Page): Promise<() => number> {
  let n = 0;
  await page.route(/\/rest\/v1\/rpc\/(set_simulation_status|save_simulation|submit_simulation_for_approval|approve_simulation)/, (route) => {
    n++;
    return route.abort();
  });
  return () => n;
}

/** /candidates → «הזמנת מועמד» → ящик «מועמד חדש». Форма не заполняется и не отправляется. */
export async function openInviteDrawer(page: Page) {
  const open = page.getByRole('button', { name: /הזמנת מועמד/ }).or(page.getByRole('link', { name: /הזמנת מועמד/ })).first();
  await expect(open).toBeVisible();
  await open.click();
  await expect(page.getByRole('heading', { name: 'מועמד חדש' })).toBeVisible();
}
